package vn.codegym.salesinventory.controller;
import jakarta.servlet.http.*;import java.util.*;import vn.codegym.salesinventory.service.*;
public final class ProductImportServlet extends PortalServlet {
 protected void get(HttpServletRequest r,HttpServletResponse s)throws Exception{if(value(r,"template").equals("1")){var sample=new ArrayList<>(List.of("SP-001","Sản phẩm mẫu","MA-NHOM","Cái","Thùng 12 cái","ACTIVE"));if(access(r).allows("COST_WRITE"))sample.add("10000");s.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");s.setHeader("Content-Disposition","attachment; filename=san-pham.xlsx");s.getOutputStream().write(Xlsx.write(List.of(ProductImportService.headers(access(r)),sample)));return;}render(r,s);}
 protected void post(HttpServletRequest r,HttpServletResponse s)throws Exception{var service=new ProductImportService(source());if(value(r,"action").equals("confirm")){var preview=(ImportPreview)r.getSession().getAttribute("productImport");if(preview==null)throw new IllegalArgumentException("Hãy tải lên tệp trước.");var result=service.confirm(actor(r).id(),preview,value(r,"token"));r.getSession().removeAttribute("productImport");r.setAttribute("report",result);r.setAttribute("successCount",result.stream().filter(ImportPreview.Line::isValid).count());r.setAttribute("failureCount",result.stream().filter(line->!line.isValid()).count());}else{var file=r.getPart("file");if(file==null||file.getSize()>Xlsx.MAX_BYTES)throw new IllegalArgumentException("Tệp XLSX tối đa 10MB.");var preview=service.preview(actor(r).id(),file.getInputStream().readNBytes(Xlsx.MAX_BYTES+1));r.getSession().setAttribute("productImport",preview);r.setAttribute("preview",preview);}render(r,s);}
 private void render(HttpServletRequest r,HttpServletResponse s)throws Exception{r.setAttribute("title","Nhập sản phẩm Excel");r.setAttribute("headers",ProductImportService.headers(access(r)));view(r,s,"imports/import");}
}
